import React from 'react';
import { Button } from 'react-native';
import { createStackNavigator } from '@react-navigation/stack';

// import VideoList from '../components/video_list';
// import VideoDetail from '../components/video_detail';

const TempSearch = (props) => (
  <Button
    onPress={() => {
      props.navigation.navigate('Detail');
    }}
    title="next"
  />
);
const TempDetail = (props) => (
  <Button
    onPress={() => {
      props.navigation.pop();
    }}
    title="close"
  />
);

const Stack = createStackNavigator();

// nest stack navigator to handle two internal views
// "name" prop is the name of the route
const SearchTab = () => {
  return (
    <Stack.Navigator>
      <Stack.Screen
        name="Search"
        component={TempSearch}
        options={{ headerShown: false }}
      />
      <Stack.Screen
        name="Detail"
        component={TempDetail}
        options={{ headerTitleStyle: { display: 'none' } }}
      />
    </Stack.Navigator>
  );
};

export default SearchTab;

screenOptions={({ route }) => ({
  tabBarIcon: ({ focused }) => {
    let iconName;

        // Customize the icon we display based on the tab route
    if (route.name === 'About') {
      iconName = 'info-circle';
    }
        // Adding the search icon
        else if (route.name === 'Search') {
      iconName = 'search';
    }

        // Return the respective icon
    return <Ionicons name={iconName} size={26} color={focused ? '#58AADA' : 'grey'} />;
  },
  headerShown: false,
})}

